import { getAddress, type Hex } from 'viem';

export function createReceipt(
    txHash: Hex,
    options: {
        from?: Hex;
        to?: Hex;
        logTopics?: Hex[];
    } = {}
) {
    return {
        transactionHash: txHash,
        from: getAddress(options.from || '0x0000000000000000000000000000000000000001'),
        to: getAddress(options.to || '0x0000000000000000000000000000000000000002'),
        logsBloom:
            '',
        logs: options.logTopics
            ? [
                  {
                      address: getAddress(options.to || '0x0000000000000000000000000000000000000002'),
                      topics: options.logTopics
                  }
              ]
            : []
    };
}
